"""Write claims_register.md: verified quotations, verification level of every reference, data provenance of every table, open issues."""
import csv, re
from pathlib import Path
D = Path(__file__).resolve().parent
q = list(csv.DictReader(open(D / "quotes.csv")))
bib = (D / "references.bib").read_text()
keys = re.findall(r"^@\w+\{([^,]+),", bib, re.M)
LEVEL = {
 "sohail2026": "full text read (open access PDF)", "rizanov2026": "full text read (open access PDF)", "zhang2024": "full text read (arXiv PDF); venue from PDF header (ICLR 2024)",
 "pozzato2023": "front matter, introduction and summary read (PDF)", "park2026": "abstract, methods summary, results and disclosures read (arXiv HTML/PDF); preprint",
 "zhao2026": "abstract and text extracted and read (arXiv PDF); preprint", "le2026": "full text read (authors' own pilot)",
 "ma2026": "full text read (open access PDF supplied by the user)", "barua2026": "full text read (open access PDF)", "benabdennour2026": "abstract and introduction read (open access PDF); described only as in its abstract",
 "severson2019": "metadata only; cell count taken from a secondary source (transformer2023)", "ma2022": "metadata and abstract only", "wang2024": "metadata; dataset description from the Zenodo record",
 "transformer2023": "arXiv text read; used only for the number of cells in the Severson data", "saha2007": "reference text copied from Sohail et al. (Q28); not independently checked",
 "kaufman2012": "abstract only", "roberts2017": "abstract only", "varma2006": "abstract only (truncated at ~700 characters)",
 "field2007": "abstract only", "benjamini1995": "metadata only", "holm1979": "NOT machine-verified: typed from the standard citation", "chen2016": "metadata only (software citation)",
 "pedregosa2011": "metadata only (software citation); JMLR record typed by texify_bib.py, not fetched", "paszke2019": "metadata only (software citation)"}
import re as _re
for _k in _re.findall(r"@\w+\{(aud\d+),", open(D / "references.bib").read()):
    LEVEL[_k] = "split/data/label passages located by keyword search in the extracted full text (audit/fulltext) and quoted; the rest of the study was not read; coded by one reader"
LEVEL["wang2024"] = "metadata; dataset description from the Zenodo record; split passage (Q-row aud33) checked in the extracted full text"
out = ["# Claims register\n", "Generated by make_register.py. Every quotation below was checked to occur verbatim in its source text (verify_quotes.py).\n",
       "## A. Verified quotations\n", "| ID | Source file | Quotation | Used for |", "|---|---|---|---|"]
out += [f"| {r['id']} | {r['source']} | \"{r['quote']}\" | {r['used_for']} |" for r in q]
out += ["\n## B. References and the depth at which they were checked\n", "Metadata (authors, title, venue, year, DOI) of all entries except saha2007 and holm1979 was fetched from Crossref or arXiv by build_bib.py.\n",
        "| Key | Checked at the level of |", "|---|---|"] + [f"| {k} | {LEVEL.get(k, 'metadata only')} |" for k in keys]
out += ["\n## C. Provenance of tables, figures and numbers\n", "All tables, both figures and every number in the prose are produced by make_tables.py from the files below and inserted by build_manuscript.py (placeholders @@key@@).\n",
        "| Item | Source file(s) |", "|---|---|",
        "| Table datasets | results/step1, step4, hust_summary.csv.gz, xjtu_features.csv.gz |", "| Table NASA, Fig. block | results/step1/reproduction_table9.csv, results/step3/block_size_curve_nasa.csv |",
        "| Table protocol, Fig. protocols | results/step8/rank_rmse.csv (from step 7 predictions) |", "| Tables holm, holmcounts | results/step11/multiplicity_reversals.csv |",
        "| Table tuning | results/step14/tuning_repeats_P3.csv (steps 7, 9, 12) |", "| Table tunprot | results/step8/rank_rmse.csv, regimes default and tuned |",
        "| Table coupling | results/step6/*/..._fast_protocol_pilot.csv (separate run, F1 and F3) |", "| Table labels | results/step8/rank_rmse.csv, labels SOH_rated and SOH_ref |",
        "| Table curve | results/step14/waveform_rmse.csv (steps 13-14) |", "| Table support | results/step10/support_strata.csv |"]
out += ["\n## C2. Numerical checks performed\n", "- Ten table entries (protocol, tuned, F2) were recomputed from the raw prediction files with separate code and matched to two decimals.", "- Two of the headline numbers added on 2026-11-01 (XJTU XGBoost, selection on the reported batches: 2.44; MATR leave-one-policy-out pooled RMSE of ridge and LightGBM: 3.29 and 4.17) were recomputed with separate code and matched.", "- The nine ranking changes surviving Holm correction were identical under bootstrap seeds 2, 3 and 4 (seed 1 is the reported run).", "- Group definitions were checked against the data: MATR policy overlap between batches (23/41/8 policies, 2 shared between batches 1 and 2, 0 with batch 3); HUST groups are identifier prefixes with 77 distinct discharge protocols."]
out += ["\n## D. Open issues the authors must resolve before submission\n",
 "1. The manuscript has not been compiled: no LaTeX engine was available in the working environment and installing one was refused. Compile with the IEEE Access template (Overleaf) and fix any errors.",
 "2. holm1979 and saha2007 are not machine-verified (see B). Check them against the originals.",
 "3. LightGBM is named in the text without a citation (no verifiable bibliographic record was obtained).",
 "4. ma2026 is cited from its abstract only (one quotation, Q18); read the article if more is to be said about it.",
 "5. park2026 and zhao2026 are preprints; park2026 declares an affiliation of three authors with the data provider (Q27).",
 "6. Section II (practice reading) rests on 28 of 60 sampled open-access studies (audit/sample_60.csv, audit/fulltext); one coder, no repeat, no prevalence claim. Screening was done by one reader on titles and abstracts.",
 "7. Author names, affiliations, funding, AI-assistance disclosure, data-availability statement, biographies and ORCID iDs are placeholders.",
 "8. The MATR files used here contain 135 cells, whereas the original description reports 124; the difference was not resolved.",
 "9. HUST groups: correction made on 2026-11-01 - the ten groups are cell-identifier groups, not discharge-protocol groups (each cell has its own discharge protocol); all earlier chat/README statements to the contrary are superseded.",
 "10. Novelty: the random-versus-cell-held-out gap on four NASA cells is already reported (le2026, barua2026) and is not claimed as new. The claim of novelty rests on the elements listed in the Introduction and on the search log in paper/novelty/ (arXiv + Crossref, 2026-11-01, not exhaustive); re-run paper/novelty/search_novelty.py shortly before submission.",
 "11. Steps 15-19 (added 2026-11-01): leave-one-policy-out on MATR (70 groups, 40 of them single-cell), selection on the reported folds (one repetition of P0/P2), preprocessing check (ridge only), charge capacity as input on XJTU. Explanations offered in the text for the selection-optimism and XJTU batch-6 results are hypotheses and are marked as untested.",
 "12. The authors of the pilot paper (le2026) are among the authors of this work; self-citation is disclosed in the Introduction."]
(D / "claims_register.md").write_text("\n".join(out) + "\n")
print("register written:", len(q), "quotations,", len(keys), "references")
